"""윷놀이 수정판 2.1 — 캐릭터 이미지 내장형.

네 캐릭터의 WebP와 배치 정보를 이 파일에 포함합니다.
assets 폴더나 외부 이미지 주소 없이 같은 그림을 표시합니다.
"""
from __future__ import annotations
import json
from functools import lru_cache
import font_bundle

_NAMES = ['heungbu', 'nolbu', 'swallow', 'gourd']
_CLASSES = ['person', 'person', 'bird', 'gourd']
_SIZES = [(64, 96), (64, 96), (96, 72), (64, 64)]
MOTION = ['walk', 'walk', 'fly', 'roll']
AVATAR_VB = ['0 0 64 64', '0 0 64 64', '0 0 96 72', '0 0 64 64']
DEFS = '<svg class="yk-defs" width="0" height="0" style="position:absolute;width:0;height:0;overflow:hidden" aria-hidden="true"><defs></defs></svg>'

_IMAGES = {'heungbu': '', 'nolbu': '', 'swallow': '', 'gourd': ''}
_LAYOUT = {'heungbu': {'width': 480, 'height': 480, 'bounds': [105, 8, 376, 470]}, 'nolbu': {'width': 480, 'height': 480, 'bounds': [110, 7, 363, 472]}, 'swallow': {'width': 480, 'height': 480, 'bounds': [15, 52, 467, 434]}, 'gourd': {'width': 480, 'height': 480, 'bounds': [49, 22, 427, 457]}}

@lru_cache(maxsize=4)
def _sprite(i: int) -> str:
    name = _NAMES[i]
    encoded = _IMAGES[name]
    meta = _LAYOUT[name]
    x0, y0, x1, y1 = meta['bounds']
    w, h = _SIZES[i]
    scale = min(w / (x1 - x0), h / (y1 - y0))
    iw, ih = meta['width'] * scale, meta['height'] * scale
    x = (w - (x1 - x0) * scale) / 2 - x0 * scale
    y = h - y1 * scale
    return (f'<svg class="spr {_CLASSES[i]}" viewBox="0 0 {w} {h}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">'
            f'<image href="data:image/webp;base64,{encoded}" x="{x:.3f}" y="{y:.3f}" width="{iw:.3f}" height="{ih:.3f}" preserveAspectRatio="none"/></svg>')

SPRITES = [_sprite(i) for i in range(4)]
HEUNGBU, NOLBU, JEBI, BAK = SPRITES
SPRITE_BASE_CSS = '.spr{display:block;overflow:visible}.spr image{pointer-events:none}'
SPRITE_CSS = font_bundle.css() + '\n' + SPRITE_BASE_CSS


def avatar(i: int) -> str:
    i %= 4
    w, h = _SIZES[i]
    return SPRITES[i].replace(f'viewBox="0 0 {w} {h}"', f'viewBox="{AVATAR_VB[i]}" style="overflow:hidden"', 1)


@lru_cache(maxsize=4)
def js_bundle(*, include_css: bool = True, include_avatars: bool = False) -> str:
    kit = {'defs': DEFS, 'spr': SPRITES, 'motion': MOTION, 'avb': AVATAR_VB}
    if include_css:
        kit['css'] = SPRITE_CSS
    if include_avatars:
        kit['av'] = [avatar(i) for i in range(4)]
    return json.dumps(kit, ensure_ascii=False)
